"use client";

import { useEffect, useRef } from "react";

const SECTIONS = [
  { id: "overview", label: "Overview" },
  { id: "competencies", label: "Competencies" },
  { id: "methodology", label: "Methodology" },
  { id: "impact", label: "Impact" },
  { id: "contact", label: "Contact" },
];

/* Ticks every 5% of viewport height; every 10% is major (28px) vs minor (14px) */
const TICKS = Array.from({ length: 21 }, (_, i) => i * 5);

export default function ScrollRuler() {
  const fillRef = useRef<HTMLDivElement | null>(null);
  const currentRef = useRef<HTMLSpanElement | null>(null);
  const nextRef = useRef<HTMLSpanElement | null>(null);

  useEffect(() => {
    const fill = fillRef.current;
    const current = currentRef.current;
    const next = nextRef.current;
    if (!fill || !current || !next) return;

    let raf = 0;
    let queued = false;

    const labelAt = (index: number) =>
      `${String(index + 1).padStart(2, "0")} / ${SECTIONS[index].label}`;

    const swap = (el: HTMLElement, text: string) => {
      if (el.textContent === text) return;
      el.classList.add("changing");
      window.setTimeout(() => {
        el.textContent = text;
        el.classList.remove("changing");
      }, 160);
    };

    const update = () => {
      const scrollable = document.documentElement.scrollHeight - window.innerHeight;
      const progress = scrollable > 0 ? Math.min(1, window.scrollY / scrollable) : 0;
      fill.style.height = `${(progress * 100).toFixed(2)}%`;

      const mid = window.scrollY + window.innerHeight * 0.5;
      let active = 0;
      for (let i = 0; i < SECTIONS.length; i += 1) {
        const section = document.getElementById(SECTIONS[i].id);
        if (section && section.offsetTop <= mid) active = i;
      }

      swap(current, labelAt(active));
      swap(next, active + 1 < SECTIONS.length ? labelAt(active + 1) : "EOF");
    };

    const onScroll = () => {
      if (queued) return;
      queued = true;
      raf = window.requestAnimationFrame(() => {
        queued = false;
        raf = 0;
        update();
      });
    };

    update();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);

    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      if (raf) window.cancelAnimationFrame(raf);
    };
  }, []);

  return (
    <aside aria-hidden className="ruler">
      {TICKS.map((pct) =>
        pct % 10 === 0 ? (
          <span key={pct} className="ruler-tick major" style={{ top: `${pct}%` }}>
            <span className="ruler-num">{String(pct).padStart(2, "0")}</span>
          </span>
        ) : (
          <span key={pct} className="ruler-tick minor" style={{ top: `${pct}%` }} />
        ),
      )}
      <div ref={fillRef} className="ruler-fill" />
      <span ref={currentRef} className="ruler-label is-current" />
      <span ref={nextRef} className="ruler-label is-next" />
    </aside>
  );
}
